import axios from 'axios';
import { QuestionResponse, UserProgress } from '../types';

const API_BASE_URL = '/api/questions';

export const askQuestion = async (question: string, description?: string, userId: string = 'default_user'): Promise<QuestionResponse> => {
  const response = await axios.post(`${API_BASE_URL}/ask`, {
    question,
    description,
    userId
  });
  return response.data;
};

export const getCategories = async (): Promise<string[]> => {
  const response = await axios.get(`${API_BASE_URL}/categories`);
  return response.data;
};

export const getUserProgress = async (userId: string = 'default_user'): Promise<UserProgress> => {
  const response = await axios.get(`${API_BASE_URL}/progress`, {
    params: { userId }
  });
  return response.data;
};

export const getUserProgressText = async (userId: string = 'default_user'): Promise<{ progress: string }> => {
  const response = await axios.get(`${API_BASE_URL}/progress/text`, {
    params: { userId }
  });
  return response.data;
};

export const clearUserHistory = async (userId: string = 'default_user'): Promise<{ message: string }> => {
  const response = await axios.post(`${API_BASE_URL}/history/clear`, { userId });
  return response.data;
};
